{
  "model": "claude-proxy/claude-fable-5-2#high",
  "permissions": [
    {
      "action": "*",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "glob",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "grep",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "question",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "skill",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "external_directory",
      "resource": "<root>/state/references/atlas/*",
      "effect": "allow"
    },
    {
      "action": "read",
      "resource": "*.env",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": "*.env.*",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": "*.pem",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": "*.key",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": "*.env.example",
      "effect": "allow"
    },
    {
      "action": "shell",
      "resource": "git status *",
      "effect": "allow"
    },
    {
      "action": "shell",
      "resource": "git diff *",
      "effect": "allow"
    },
    {
      "action": "shell",
      "resource": "git log *",
      "effect": "allow"
    },
    {
      "action": "shell",
      "resource": "git show *",
      "effect": "allow"
    },
    {
      "action": "shell",
      "resource": "mermaid-render *",
      "effect": "allow"
    },
    {
      "action": "repo_refresh_refresh_origin",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "repo_refresh_read_origin_file",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "subspace_*",
      "resource": "*",
      "effect": "allow"
    }
  ],
  "providers": {
    "claude-proxy": {
      "name": "Fleet model proxy, Claude family",
      "package": "@opencode/ai/providers/anthropic-compatible",
      "settings": {
        "baseURL": "http://127.0.0.1:8317/v1",
        "apiKey": "{env:CLIPROXYAPI_API_KEY}"
      },
      "models": {
        "claude-fable-5-2": {
          "name": "claude-fable-5-2",
          "capabilities": {
            "input": [
              "text",
              "image"
            ]
          }
        }
      }
    }
  },
  "mcp": {
    "servers": {
      "subspace": {
        "type": "remote",
        "url": "http://127.0.0.1:3001/mcp",
        "headers": {
          "X-Subspace-Agent": "example-atlas"
        }
      },
      "subspace_files": {
        "type": "local",
        "command": [
          "/usr/bin/python3",
          "-I",
          "/opt/subspace-fleet/lib/officer_upload.py",
          "http",
          "http://127.0.0.1:3001/mcp",
          "example-atlas"
        ]
      },
      "repo_refresh": {
        "type": "local",
        "command": [
          "/usr/bin/python3",
          "/opt/subspace-fleet/lib/repo_refresh.py",
          "mcp"
        ],
        "timeout": 110000
      }
    }
  }
}

